impl Video {pub fn export_digits(&self,path:&str){let zero=self.read(0x2000+8*32+22);println!("zero tile{} ctrl{}",zero,self.ctrl);let bank=(self.ctrl as usize&0x10)<<8;let mut img=image::RgbaImage::new(80,8);for digit in 0..10{let tile=zero as usize+digit;for y in 0..8{let lo=self.read(bank+tile*16+y);let hi=self.read(bank+tile*16+y+8);for x in 0..8{let val=((lo>>(7-x))&1)|(((hi>>(7-x))&1)<<1);let c=if val==0{0}else{255};img.put_pixel((digit*8+x)as u32,y as u32,image::Rgba([c,c,c,255]));}}}img.save(path).unwrap();}}
